// src/config/ConfigMerger.ts
class ConfigMerger {
  static merge(userConfig) {
    const config = ConfigDefaults.getDefaultConfig();
    if (userConfig.enforceTodoTracker !== undefined) {
      config.enforceTodoTracker = userConfig.enforceTodoTracker;
    }
    if (userConfig.goals !== undefined) {
      config.goals = userConfig.goals;
    }
    if (userConfig.planDirectory !== undefined) {
      config.planDirectory = userConfig.planDirectory;
    }
    if (userConfig.readOnlyTools !== undefined) {
      config.readOnlyTools = userConfig.readOnlyTools;
    }
    if (userConfig.skillMappings !== undefined) {
      for (const command of ConfigTypes.getSkillCommands()) {
        config.skillMappings[command] = userConfig.skillMappings[command] ?? config.skillMappings[command];
      }
    }
    if (userConfig.writeCapableTools !== undefined) {
      config.writeCapableTools = userConfig.writeCapableTools;
    }
    return config;
  }
}

// src/config/ConfigValidator.ts
class ConfigValidator {
  static validate(config) {
    const errors = [];
    if (config.planDirectory.trim() === "") {
      errors.push("Invalid planDirectory: must be a non-empty string.");
    }
    for (const [option, tools] of [["readOnlyTools", config.readOnlyTools], ["writeCapableTools", config.writeCapableTools]]) {
      if (tools.some((tool) => tool.trim() === "")) {
        errors.push(`Invalid ${option}: tool names must be non-empty strings.`);
      }
    }
    for (const command of ConfigTypes.getSkillCommands()) {
      if (config.skillMappings[command].trim() === "") {
        errors.push(`Invalid skillMappings.${command}: must be a non-empty string.`);
      }
    }
    return { valid: errors.length === 0, errors };
  }
  static validateOrThrow(config) {
