// src/config/ConfigLoader.ts
class ConfigLoader {
  static stringOption(value) {
    return typeof value === "string" && value.trim() !== "" ? value : undefined;
  }
  static planDirectoryOption(value) {
    const directory = this.stringOption(value)?.replace(/\/+$/, "");
    return directory === "" ? undefined : directory;
  }
  static booleanOption(value) {
    return typeof value === "boolean" ? value : undefined;
  }
  static toolNamesOption(value) {
    if (!Array.isArray(value)) {
      return;
    }
    const toolNames = [];
    for (const valueTool of value) {
      const tool = this.stringOption(valueTool);
      if (tool === undefined) {
        return;
      }
      toolNames.push(tool);
    }
    return toolNames;
  }
  static skillMappingsOption(value) {
    if (typeof value !== "object" || value === null) {
      return;
    }
    const mappingOptions = value;
    const skillMappings = {};
    for (const command of ConfigTypes.getSkillCommands()) {
      const skill = this.stringOption(mappingOptions[command]);
      if (skill !== undefined) {
        skillMappings[command] = skill;
      }
    }
    return skillMappings;
  }
  static getUserConfig(options) {
    const enforceTodoTracker = this.booleanOption(options?.enforceTodoTracker);
    const goals = this.booleanOption(options?.goals);
    const planDirectory = this.planDirectoryOption(options?.planDirectory);
    const readOnlyTools = this.toolNamesOption(options?.readOnlyTools);
    const skillMappings = this.skillMappingsOption(options?.skillMappings);
    const writeCapableTools = this.toolNamesOption(options?.writeCapableTools);
    return {
      ...enforceTodoTracker === undefined ? {} : { enforceTodoTracker },
      ...goals === undefined ? {} : { goals },
      ...planDirectory === undefined ? {} : { planDirectory },
      ...readOnlyTools === undefined ? {} : { readOnlyTools },
      ...skillMappings === undefined ? {} : { skillMappings },
      ...writeCapableTools === undefined ? {} : { writeCapableTools }
    };
  }
  static loadConfig(options) {
    try {
      const config = ConfigMerger.merge(this.getUserConfig(options));
      ConfigValidator.validateOrThrow(config);
      return config;
    } catch {
      return ConfigDefaults.getDefaultConfig();
    }
  }
}
